#!/usr/bin/env python3
"""Generated single-file runtime for the active Football C + C2 /xi path.

This portable bundle intentionally excludes retired C3/C4 execution and the
legacy decision-triplet runner. Historical C3/C4 source may remain elsewhere
in the repository for audit history, but new Step-2 execution is C+C2 only.
"""

from __future__ import annotations

import argparse
import json
import sys
import types
from pathlib import Path
from typing import Any

MIN_PYTHON = (3, 10)

SOURCE_BLOB_SHA = {
  "models/football/engine/competition_reliability.py": "03375017a0a0a80101472abeec55d0b912419444",
  "models/football/engine/core.py": "591aa29fce39a9c2af04973312ea163c8ed7c774",
  "models/football/engine/adapter.py": "a2e2095f71b66992e47a5a78f75f12b355e9a61a",
  "models/football/engine/step2_reconcile.py": "0367d7145019e8fae360fd8003848020ff908085",
  "models/football/engine/model_bet_accounting.py": "cceb30fd8a1c0fa3b051d258de7538a47a885438"
}
def _restore_pinned_sources(blob: str) -> dict[str, str]:
    """Decode the generated self-contained source bundle; Git blob pins still apply."""
    import base64
    data = base64.b64decode(blob)
    output = bytearray()
    cursor = 0
    while cursor < len(data):
        tag = data[cursor]
        cursor += 1
        if tag < 128:
            size = tag + 1
            output.extend(data[cursor:cursor + size])
            cursor += size
        else:
            size = tag - 128 + 4
            distance = (data[cursor] << 8) | data[cursor + 1]
            cursor += 2
            if not 0 < distance <= len(output):
                raise ValueError("invalid source-backreference")
            for _ in range(size):
                output.append(output[-distance])
    return json.loads(output.decode("ascii"))


SOURCES = _restore_pinned_sources("")

