def _install_modules() -> None:
    for name in INSTALL_ORDER:
        source = SOURCES[name]
        module = types.ModuleType(name)
        module.__file__ = f"<xi_portable:{name}>"
        sys.modules[name] = module
        exec(compile(source, module.__file__, "exec"), module.__dict__)


def self_check() -> dict[str, Any]:
    if sys.version_info[:2] < MIN_PYTHON:
        return {
            "ok": False,
            "status": "XI PORTABLE RUNTIME: FAIL",
            "error": f"Python {MIN_PYTHON[0]}.{MIN_PYTHON[1]}+ required",
        }
    try:
        _install_modules()
        from adapter import run_decision
        from step2_reconcile import reconcile_step2
        from model_bet_accounting import compile_fixture_accounting
    except Exception as exc:
        return {
            "ok": False,
            "status": "XI PORTABLE RUNTIME: FAIL",
            "error": f"{type(exc).__name__}: {exc}",
        }

    if not all(callable(x) for x in (run_decision, reconcile_step2, compile_fixture_accounting)):
        return {
            "ok": False,
            "status": "XI PORTABLE RUNTIME: FAIL",
            "error": "required C+C2 Step-2/accounting callables are missing",
        }

    return {
        "ok": True,
        "status": "XI PORTABLE RUNTIME: PASS",
        "active_models": ["c", "c2"],
        "python_version": ".".join(map(str, sys.version_info[:3])),
        "embedded_modules": list(INSTALL_ORDER),
        "source_blob_sha": SOURCE_BLOB_SHA,
    }


def _load(path: str) -> dict[str, Any]:
    return json.loads(Path(path).read_text(encoding="utf-8"))


def _pair_epoch_signature(payload: dict[str, Any]) -> str:
    match = payload.get("match")
    context = payload.get("context")
    if not isinstance(match, dict):
        raise ValueError("C+C2 pair requires match object")
    if not isinstance(context, dict):
        raise ValueError("C+C2 pair requires context object")
    frozen = {
        "match": {key: match.get(key) for key in COMMON_MATCH_FIELDS},
        "context": {key: context.get(key) for key in COMMON_CONTEXT_FIELDS},
    }
    return json.dumps(frozen, sort_keys=True, separators=(",", ":"))


def run_football_pair_files(c: str, c2: str) -> dict[str, Any]:
    """Run C/C2 football hypotheses with no bookmaker quote requirements."""
    _install_modules()
    from adapter import run_football_assessment
    payloads = {"c": _load(c), "c2": _load(c2)}
    signatures = set()
    for model in ("c", "c2"):
        payload = payloads[model]
        if str(payload.get("model", "")).lower() != model:
            raise ValueError(f"football pair expected model={model}")
        if payload.get("stage") != "football_assessment":
            raise ValueError("football-pair needs stage=football_assessment")
        match, ctx = payload.get("match"), payload.get("context")
        if not isinstance(match, dict) or not isinstance(ctx, dict):
            raise ValueError("football pair requires match and context objects")
        eid = payload.get("evidence_epoch_id")
        if not isinstance(eid, str) or not eid.strip():
            raise ValueError("football pair requires evidence_epoch_id")
        at = ctx.get("assessment_at_utc")
        if not isinstance(at, str) or not at.strip():
            raise ValueError("football pair requires assessment_at_utc")
        signatures.add(json.dumps({
            "match_id": match.get("match_id"),
            "kickoff_ict": match.get("kickoff_ict"),
            "evidence_epoch_id": eid, "assessment_at_utc": at,
            "fixture_status": ctx.get("fixture_status"),
            "score": ctx.get("score"), "match_minute": ctx.get("match_minute"),
            "material_event_since_frozen": ctx.get("material_event_since_frozen"),
        }, sort_keys=True))
    if len(signatures) != 1:
        raise ValueError("C+C2 football pair evidence epoch/status/score mismatch")
    results = {m: run_football_assessment(payloads[m]) for m in ("c", "c2")}
    return {
        "engine_execution_status": "EXECUTED_C_C2_FOOTBALL_ONLY",
        "models_executed": ["c", "c2"], "quotes_required": False,
        "quote_research_required": False, "model_bets_created": False,
        "model_accounting_status": "NONE", "results": results,
    }


def run_pair_files(c: str, c2: str) -> dict[str, Any]:
    """Execute active C+C2 validators atomically from one frozen evidence epoch."""
    _install_modules()
    from adapter import run_decision

    payloads = {"c": _load(c), "c2": _load(c2)}
    signatures = set()

    for model in ("c", "c2"):
        payload = payloads[model]
        actual = str(payload.get("model", "")).lower()
        if actual != model:
            raise ValueError(
                f"pair payload mismatch: expected model={model}, got {actual or '<missing>'}"
            )
        if payload.get("stage") != "decision":
            raise ValueError(f"pair payload model={model} must use stage=decision")
        signatures.add(_pair_epoch_signature(payload))

    if len(signatures) != 1:
        raise ValueError(
            "C+C2 pair must share the same frozen common evidence epoch"
        )

    results = {model: run_decision(payloads[model]) for model in ("c", "c2")}

    return {
        "engine_execution_status": "EXECUTED_C_C2_PAIR",
        "models_executed": ["c", "c2"],
        "results": results,
    }


def run_reconcile_file(path: str) -> dict[str, Any]:
    _install_modules()
    from step2_reconcile import reconcile_step2
    return reconcile_step2(_load(path))


def run_accounting_file(path: str) -> dict[str, Any]:
    _install_modules()
    from model_bet_accounting import compile_fixture_accounting
    return compile_fixture_accounting(_load(path))


def main() -> int:
    parser = argparse.ArgumentParser(
        description="Portable Football /xi C+C2 deterministic runtime"
    )
    sub = parser.add_subparsers(dest="command", required=True)
    sub.add_parser("self-check")
    # Short user-stage names. Historical names retained for old scripts.
    one = sub.add_parser("xi")
    one.add_argument("--c", required=True)
    one.add_argument("--c2", required=True)
    pair = sub.add_parser("pair")
    pair.add_argument("--c", required=True)
    pair.add_argument("--c2", required=True)
    price = sub.add_parser("bet-check")
    price.add_argument("--c", required=True)
    price.add_argument("--c2", required=True)
    football_pair = sub.add_parser("football-pair")
    football_pair.add_argument("--c", required=True)
    football_pair.add_argument("--c2", required=True)
    assess = sub.add_parser("assess")
    assess.add_argument("--c", required=True)
    assess.add_argument("--c2", required=True)
    reconcile = sub.add_parser("reconcile")
    reconcile.add_argument("--input", required=True)
    accounting = sub.add_parser("accounting")
    accounting.add_argument("--input", required=True)
    args = parser.parse_args()

    try:
        if args.command == "self-check":
            result = self_check()
            print(json.dumps(result, indent=2, sort_keys=True))
            return 0 if result.get("ok") else 2
        if args.command == "xi":
            c_input, c2_input = _load(args.c), _load(args.c2)
            mode1, mode2 = c_input.get("stage"), c2_input.get("stage")
            if mode1 != mode2:
                raise ValueError("C+C2 must use the same /xi mode and current match epoch")
            if mode1 == "football_assessment":
                result = run_football_pair_files(args.c, args.c2)
                display_mode = "FOOTBALL_ASSESSMENT"
            elif mode1 == "decision":
                result = run_pair_files(args.c, args.c2)
                display_mode = "FOOTBALL_AND_PRICE_CHECK"
            else:
                raise ValueError("/xi expects stage=football_assessment or stage=decision")
            print(json.dumps({"ok": True, "xi_mode": display_mode, **result},
                             indent=2, sort_keys=True))
            return 0
        if args.command in {"pair", "bet-check"}:
            result = run_pair_files(args.c, args.c2)
            print(json.dumps({"ok": True, **result}, indent=2, sort_keys=True))
            return 0
        if args.command in {"football-pair", "assess"}:
            result = run_football_pair_files(args.c, args.c2)
            print(json.dumps({"ok": True, **result}, indent=2, sort_keys=True))
            return 0
        if args.command == "reconcile":
            result = run_reconcile_file(args.input)
            print(json.dumps({"ok": True, "step2_reconciliation_status": "PASS", **result}, indent=2, sort_keys=True))
            return 0
        result = run_accounting_file(args.input)
        print(json.dumps({"ok": True, **result}, indent=2, sort_keys=True))
        return 0
    except Exception as exc:
        error_type = type(exc).__name__
        contract_types = {
            "ContractError",
            "Step2ReconciliationError",
            "ModelBetAccountingError",
            "ValueError",
            "KeyError",
            "JSONDecodeError",
        }
        is_contract = error_type in contract_types
        print(json.dumps({
            "ok": False,
            "status": "XI ENGINE CONTRACT REJECTED" if is_contract else "XI PORTABLE RUNTIME: EXECUTION FAILED",
            "failure_class": "PAYLOAD_OR_MODEL_CONTRACT" if is_contract else "PYTHON_OR_RUNTIME",
            "error_type": error_type,
            "error": str(exc),
        }, indent=2, sort_keys=True), file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
